import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';
import { CartSummary } from './CartSummary';
import { CartProvider } from '../state/CartContext';
import { CartState } from '../types/cart';

function renderCartSummary(initialState: CartState) {
  return render(
    <CartProvider initialState={initialState}>
      <CartSummary />
    </CartProvider>
  );
}

const sampleItems = [
  { id: '1', name: 'Produto A', price: 100, quantity: 2 },
  { id: '2', name: 'Produto B', price: 50, quantity: 1 },
];

const initialStateWithItems: CartState = {
  items: sampleItems,
  couponCode: null,
};

const initialStateWithCoupon: CartState = {
  items: sampleItems,
  couponCode: 'PROMO10',
};

describe('CartSummary', () => {
  it('Renderiza mensagem de carrinho vazio', () => {
    renderCartSummary({ items: [], couponCode: null });

    expect(screen.getByText('Seu carrinho está vazio.')).toBeInTheDocument();
  });

  it('Renderiza itens do carrinho', () => {
    renderCartSummary(initialStateWithItems);

    sampleItems.forEach((item) => {
      expect(screen.getByText(`${item.name} × ${item.quantity}`)).toBeInTheDocument();
      expect(screen.getByText(new RegExp(`R\$\s*${(item.price * item.quantity).toFixed(2).replace('.', ',').replace(/\s/g, '\\s?')}`))).toBeInTheDocument();
    });
  });

  it('Aplica cupom válido', async () => {
    const user = userEvent.setup();
    renderCartSummary(initialStateWithItems);

    await user.type(screen.getByLabelText('Cupom de desconto'), 'PROMO10');
    await user.click(screen.getByRole('button', { name: 'Aplicar' }));

    expect(screen.getByText('Cupom PROMO10 aplicado.')).toBeInTheDocument();
  });

  it('Exibe erro para cupom inválido', async () => {
    const user = userEvent.setup();
    renderCartSummary(initialStateWithItems);

    await user.type(screen.getByLabelText('Cupom de desconto'), 'INVALID');
    await user.click(screen.getByRole('button', { name: 'Aplicar' }));

    expect(screen.getByRole('alert')).toHaveTextContent('Cupom inválido.');
  });

  it('Remove item do carrinho', async () => {
    const user = userEvent.setup();
    renderCartSummary(initialStateWithItems);

    await user.click(screen.getByRole('button', { name: 'Remover Produto A' }));

    expect(screen.queryByText('Produto A × 2')).not.toBeInTheDocument();
  });

  it('Remove cupom aplicado', async () => {
    const user = userEvent.setup();
    renderCartSummary(initialStateWithCoupon);

    await user.click(screen.getByRole('button', { name: 'Remover cupom' }));

    expect(screen.queryByText('Cupom PROMO10 aplicado.')).not.toBeInTheDocument();
  });

  it('Esvazia o carrinho', async () => {
    const user = userEvent.setup();
    renderCartSummary(initialStateWithItems);

    await user.click(screen.getByRole('button', { name: 'Esvaziar carrinho' }));

    expect(screen.getByText('Seu carrinho está vazio.')).toBeInTheDocument();
  });

  it('Calcula subtotal, desconto e total corretamente', () => {
    renderCartSummary(initialStateWithCoupon);

    expect(screen.getByTestId('subtotal')).toHaveTextContent(new RegExp('R\$\s*250,00'.replace(/\s/g, '\\s?')));
    expect(screen.getByTestId('discount')).toHaveTextContent(new RegExp('-R\$\s*25,00'.replace(/\s/g, '\\s?')));
    expect(screen.getByTestId('total')).toHaveTextContent(new RegExp('R\$\s*225,00'.replace(/\s/g, '\\s?')));
  });
});
